export const blurbs: Record<string, string> = {
 "f-wd1212842": "На заседании гаражного кооператива предстоит выбрать четырёх «крайних», которые должны сами отказаться от будущего собственного гаража. Что чувствуешь, голосуя за список отверженных, в котором нет твоей фамилии? Неловкость и облегчение. А если фамилия есть? Смирись, ведь всё уже согласовано. Но произошёл бунт...",
 "f-wd180214": "У примы балетного театра неожиданно появляется опасная конкурентка, способная отобрать у неё все партии. Соперничество усиливается по мере приближения ответственного выступления.",
 "f-wd58815115": "Молодая невеста теперь часть семьи своего новоиспечённого мужа, богатого эксцентричного рода, чтящего вековые традиции. Кто бы мог подумать, что первая брачная ночь превратится в смертельную игру с новообретёнными родственниками, в которой девушке нужно будет очень постараться, чтобы дожить до рассвета.",
 "f-wd380667": "Наемник Ройс невольно вынужден возглавить группу профессионалов, выполняющих загадочную миссию на неизвестной планете. За исключением опального доктора все они - хладнокровные убийцы: наемники, гангстеры, осужденные и участники отрядов смерти - людские «хищники». Но когда их начинает систематически преследовать и истреблять невообразимое чудовище, становится очевидно, что теперь они в роли своих жертв.",
 "f-wd125131076": "Когда неудачливый продавец мебели Кларк обнаруживает скрытый портал в другое измерение в подвале своего магазина, он оказывается в бесконечном лабиринте извилистых жёлтых коридоров. В этом мире время и пространство не подчиняются логике, а нечто жуткое может скрываться за каждым углом.",
 "f-wd1058512": "К 2017 году излюбленным развлечением для жителей Америки становится садистское телешоу «Бегущий человек», в котором заключённые должны пройти суровые испытания и получить свободу, либо умереть на глазах телезрителей от рук преследователей-охотников. Однажды среди участников оказывается полицейский Бен Ричардс, отказавшийся расстрелять безоружную толпу голодных людей. Теперь вместе с собратьями по несчастью ему предстоит принять участие в безумной гонке со смертью.",
 "f-wd209667": "Современный Мадрид. Раймунда — привлекательная молодая испанка живет с безработным мужем и подрастающей красавицей-дочерью. Семье катастрофически не хватает денег и поэтому ей приходится трудиться сразу на нескольких работах. Раймунда — сильный, волевой человек, прирожденный боец, но, как всякая женщина, она невероятно ранима. С самого детства она хранит тайну…",
 "f-wd637842": "Молодая мать, отчаявшись найти лекарство от таинственного заболевания своей дочери Шэрон, отказывается отдать её в психиатрическую лечебницу. Вместе с Шэрон она отправляется в Сайлент Хилл, город, название которого её дочь постоянно твердит во сне. Несмотря на сопротивление мужа, Роуз убеждена, что найдёт там ответы, в которых так нуждается. Но когда они подъезжают к заброшенному городу, на дороге появляется таинственная фигура, Роуз резко тормозит, и машина попадает в аварию… Придя в себя, она обнаруживает, что Шэрон исчезла…",
 "f-wd22077183": "Лайт Тёрнер находит сверхъестественную тетрадь, с помощью которой может призывать смерть. Это привлекает внимание его одноклассницы, детектива и дьявола.",
 "f-wd40187": "Два падших ангела Локи и Бартлби, обречённые вечно торчать в штате Висконсин, узнают, что у них есть шанс вернуться в рай. Для этого нужно всего лишь воспользоваться католической догмой, провозглашенной кардиналом-новатором: каждый прошедший через освященную арку в соборе в Нью-Джерси получает отпущение грехов.  Есть только одно но. Если это произойдет, то исчезнет всё сущее на земле, включая род людской. Помешать этому может только пра-пра... пра-пра племянница Иисуса Христа по имени Вифания, которой помогают тринадцатый апостол Руфус и два смертных пророка. К ним присоединяется уже давно живущая на земле Муза по имени Серендипити, подрабатывающая стриптизёршей.",
 "f-wd65768589": "Мастеру боевых искусств Шан-Чи предстоит противостоять призракам из собственного прошлого, по мере того как его втягивают в паутину интриг таинственной организации \"Десять колец\".",
 "f-wd53911403": "474 дня прошло после нападения на Землю охотящихся на звук существ, семья Эбботт продолжает бороться за жизнь в полной тишине. Столкнувшись со смертельной угрозой в собственном доме, они вынуждены отправиться во внешний мир, где находят убежище и старого знакомого семьи. Поймав радиосигнал, Реган вычисляет место предполагаемой колонии выживших и решает во что бы то ни стало её разыскать.",
 "f-wd19742713": "Во времена Холодной войны секретная организация «Патриот» создала отряд супергероев, в который вошли участники из различных советских республик. Долгие годы героям приходилось скрывать свою сущность, однако в тяжелые для страны времена они вновь берутся за дело.",
 "f-wd106725458": "Декабрь 1941 года. Летчик Николай Комлев успешно выполняет приказ и уничтожает немецкую танковую колонну, движущуюся к Москве. Но самолет Комлева подбит вражескими истребителями, и летчик чудом сажает свой ИЛ-2 на глухую лесную поляну. Кажется, самое страшное позади - он выжил в воздушном бою. Однако испытания только начинаются: раненому Комлеву предстоит проделать немыслимый путь, превозмогая мороз, боль и голод, спасаясь от волков и спецотряда нацистов, задача которых - найти его во что бы то ни стало. Летчика ведут воля к жизни, мужество и, конечно, любовь. Дома его ждет Ольга, именно ее образ согревает его в стужу и помогает двигаться вперед, к спасению. У него лишь один шанс выжить, чтобы вернуться к любимой, снова подняться в небо и победить.",
 "f-wd30880032": "Казаки, ведьмы, русалки, утопленницы и другие обитатели Диканьки встречаются лицом к лицу со своим создателем Николаем Гоголем, молодым писарем из Петербурга, который страдает загадочными припадками и может общаться с персонажами из потустороннего мира. Вместе со своим начальником, блестящим столичным следователем Яковым Гуро, начинающий писатель приезжает на Полтавщину расследовать таинственные убийства девушек. Здесь же он встречает свою любовь, которой суждено сыграть роковую роль в его судьбе. Но хватит ли юному литератору духу противостоять невообразимому? Ведь по слухам, которые активно разносят напуганные местные жители, за преступлениями стоит не кто иной, как сам Дьявол в обличии Чёрного всадника.",
 "f-wd4421399": "Жили-были двое бездомных сирот. Маленький Май обладал необыкновенным даром находить спрятанное золото. Однажды в рождественскую ночь злой и жадный Горгон, переодевшись Дедом Морозом, украл мальчика. И тогда Марта отправилась на поиски брата. В этом нелёгком пути её сопровождал весёлый и добрый друг Орландо — врач, поэт, философ, путешественник. Пока Марта искала брата, Май превратился в жадного и черствого человека. Но терпение, любовь, надежда и новый друг помогли девочке воскресить его душу.",
 "f-wd105359456": "О приключениях бывшего мелкого преступника Скотта Лэнга, ставшего обладателем костюма, позволяющего уменьшаться и увеличиваться в размерах. Вместе с напарницей Хоуп ван Дайн, дочерью известного физика и энтомолога Хэнка Пима, разработавшего костюм человека-муравья, Скотт вновь спасает мир от предстоящей угрозы.",
 "f-wd898465": "Киноверсия легендарной рок-оперы композитора Эндрю Ллойда Уэббера на стихи Тима Райса, сделанная в форме спектакля, разыгранного современными актерами на фоне живописных ближневосточных пейзажей.",
 "f-wd136565785": "Медицинский курьер Брайан отправляется выполнить обычную доставку, но внезапно оказывается в центре кошмарной вспышки, охватившей Раккун-Сити. Город погружается в хаос, а на улицах появляются заражённые люди и чудовищные существа. Оказавшись один на один с надвигающейся угрозой, Брайан вынужден искать путь через охваченный катастрофой город, используя всё, что может помочь ему выжить. С каждой минутой ситуация становится всё опаснее, превращая простую доставку в отчаянную борьбу за жизнь.",
 "f-wd107105860": "Астронавт Райленд Грейс просыпается на космическом корабле, не помня ни себя, ни свою миссию. Постепенно мужчина приходит к выводу, что он — единственный выживший из экипажа, отправленного в звёздную систему Тау Кита в поисках спасения от катастрофы на Земле. Райленду предстоит положиться на свои обширные научные знания, изобретательность и силу воли, но, возможно, ему не придётся искать в одиночку.",
 "f-wd112865900": "Битлджус возвращается! После неожиданной семейной трагедии три поколения семьи Дотс возвращаются домой в Уинтер-Ривер. Жизнь Лидии переворачивается с ног на голову, когда ее непокорная дочь-подросток Астрид обнаруживает на чердаке таинственную модель города и случайно открывается портал в загробную жизнь. Поскольку в обоих мирах назревают неприятности, это только вопрос времени, когда кто-нибудь трижды произнесет имя Битлджуса, и озорной демон вернется, чтобы устроить свой собственный беспредел.",
 "f-wd115859490": "Соник, Наклз и Тейлз воссоединяются против нового могущественного противника, Ежа Шэдоу, таинственного злодея с силами, не похожими ни на что, с чем они сталкивались раньше. Команда Соника вынуждена создать неожиданный союз в надежде остановить Шэдоу и защитить планету.",
 "f-wd124380480": "Спустя 5 лет после завоевания мира юрского периода, экспедиция отправляется в изолированные экваториальные регионы, чтобы извлечь ДНК из 3-ёх огромных доисторических существ для революционного открытия в медицине.",
 "f-wd832047": "После миссии в Бейруте лейтенант полиции Лос-Анджелеса Фрэнк Дребин возвращается на родину. Здесь он узнаёт, что его бросила девушка, а коллега Нордберг получил тяжёлые ранения. Дребин берётся за расследование, постоянно попадая в нелепые ситуации. Он ещё не подозревает, что вскоре окажется в эпицентре заговора.",
 "f-wd219424": "Год назад на Хэллоуин 6-ро друзей случайно сбили на автомобиле незнакомого мужчину и, не желая брать на себя ответственность, спрятали тело убитого. За прошедшее время они свыклись с мыслью, что убийство сошло им с рук, однако ситуация меняется, когда неизвестный человек отправляет записку Синди, в которой описаны подробности дорожно-транспортного происшествия. Вскоре таинственный очевидец инцидента раскрывает свою личность, и друзья с ужасом понимают, что им предстоит противостоять сумасшедшему серийному убийце.",
 "f-wd124262351": "Бразилия, 1971 год. В стране уже шесть лет свирепствует военная диктатура. Инженер Рубенс Пайва, многодетный отец и любящий муж, некогда бывший конгрессменом, готовится облагородить семейное гнёздышко в Рио-де-Жанейро, но в дом приходят солдаты и увозят Рубенса на допрос, с которого он так и не возвращается. Его жена Юнис начинает борьбу за правду и пытается вернуть любимого.",
 "f-wd191753": "Золушка — бедная сиротка, которую злая мачеха и ее вздорные дочки, заставляют тяжко работать с утра до ночи. Она так хочет попасть на королевский бал. На помощь бедняжке приходит Добрая фея! Силой волшебства она наделяет Золушку роскошной каретой, чудесным платьем и необыкновенными хрустальными башмачками.",
 "f-wd215365": "Давным-давно, в те времена, когда по Земле ходили мамонты, а вечные льды достигали южных морей, жил охотник по имени Кенаи. Он был храбр и ловок, но однажды прогневил Великих Духов, убив медведицу — священного для него зверя, чей тотем он носил на шее. Тогда духи предков в наказание превратили в медведя самого Кенаи. Теперь он не может говорить по-человечески, за ним охотится его собственный брат, а ещё к нему прибился озорной медвежонок Кода, не желающий оставить героя в покое. Но духи не зря свели Кенаи с Кодой — в час, когда охотник увидит в медвежонке родственную душу, он сможет снова стать человеком…",
 "f-wd334132": "Оливия обращается за помощью к Базилю с Бэйкер-стрит. Она просит найти исчезнувшего отца. Базиль, его друг и соратник доктор Доусон, а также пес Тоби берутся за расследование. Следы ведут к профессору Ратигану, крупному преступнику, которому Базилю и придется противостоять.",
 "f-wd204662": "В стародавние времена в центре Лондона появился громадный камень с замурованным в нем старинным мечом. Золотая надпись на мече гласила, что королем Англии станет тот, кто вытащит этот заколдованный меч, доказав тем самым свою особую силу и право на власть. Пока это не удавалось никому.",
 "f-wd273978": "Легендарный мастер боевых искусств Ли Мубай отправляется на поиски магического меча зеленой стали, похищенного тайными злоумышленниками. Впереди его ждет зловещая фигура давнего противника, наемного убийцы, который после долгого отсутствия снова вернулся на тропу войны…",
 "f-wd15079318": "История отношений между известным физиком Стивеном Хокингом и его женой.",
 "f-wd641362": "Майк с детства мечтает стать профессиональным пугателем и поступает в престижный Университет монстров, чтобы осуществить свою главную мечту. Там он неожиданно знакомится с Джеймсом Салливаном - уверенным в себе монстром, который привык полагаться на свои природные способности. Сначала Майк и Салли становятся соперниками и совершенно не ладят друг с другом. Но после неожиданного исключения с факультета пугателей, им приходится объединиться и вместе участвовать в университетских соревнованиях. Чтобы вернуть себе возможность стать пугателями, 2-ум совершенно разным монстрам предстоит научиться работать в команде, преодолеть соперничество и понять, что настоящая дружба может начаться с самой большой неприязни.",
 "f-wd152857": "Апрель 1945 года. Советские войска сжимают кольцо вокруг столицы Третьего рейха - Берлина. Перед лицом неминуемого поражения нацистская верхушка ищет спасение в секретном бункере, не желая покидать обезумевшего фюрера. Отвергнув предложения о побеге, Гитлер утверждает, что победа близка. Он приказывает сравнять Германию с землёй и обсуждает детали своего самоубийства. Последнее убежище палачей пронизано агонией и страхом. И лишь те, кто выйдут живыми из этого бетонного ада, смогут поведать историю о последних минутах жизни и мрачном падении диктатора и его режима.",
 "f-wd60997779": "Миллион лет миньоны искали самого великого и ужасного предводителя, пока не встретили Грю. Пусть он ещё очень молод, но у него в планах по-настоящему гадкие дела, которые заставят планету содрогнуться.",
 "f-wd980041": "Главный герой — молодой газетный репортёр Тинтин. Благодаря своей профессии он путешествует по всему миру и становится участником увлекательных приключений.",
 "f-wd171711": "Вернувшись на Землю, команда корабля «Энтерпрайз» обнаруживает, что деятельность и принципы их организации подорваны изнутри. Флот скован необъяснимым ужасом и бездействует, пока мир все глубже погружается в бездну.  Капитан Кирк берет на себя руководство операцией по поимке злодея, ответственного за этот хаос и способного уничтожить все человечество.  В запутанной игре не на жизнь, а на смерть, любовь и дружба будут принесены в жертву ради единственного, что осталось у Кирка — его команды.",
 "f-wd204398": "При таинственных обстоятельствах погибает коллега Джеймса Бонда агент 009. Чтобы разобраться в этом преступлении Бонду предстоит прокатиться в Индию, где он встречается с роковой женщиной, умопомрачительной красоткой по прозвищу Осьминожка. Активно пользуясь своими глубочайшими знаниями женской психологии, агент 007 выходит на след абсолютно безумного и столь же амбициозного отставного русского генерала, который мечтает развязать третью мировую войну и захватить все Европейские государства. Несмотря на то, что Бонд использует всевозможные приспособления из шпионского арсенала, даже летает на миниатюрном реактивном самолетике, оставить его в живых или убить решает таинственная красавица.",
 "f-wd18703032": "Джой похитил маньяк, когда она была подростком. С тех пор она живет в крохотной комнатке вместе со своим 5-летним сыном Джеком. Мальчик ничего кроме этой комнаты не видел — он в ней родился и ни разу её не покидал. Все эти годы Джой вынашивала план, побега и вот у нее появился шанс.",
 "f-wd208204": "Писатель-неудачник Дж. Меттью Барри не повинуется законам консервативного Лондона и становится другом одинокой вдовы, а также приемным отцом ее четырем маленьким сыновьям. Новая семья дарит вдохновение: писатель создает детского героя Питера Пена и чудесную сказку о детях, которые не хотят взрослеть…",
 "f-wd630032": "У слоненка Хортона такие большие уши, что он, оказывается, может слышать даже то, как с ним говорит цветок. Вернее, существа, которые живут в нем. Но если слоненок начинает говорить и прислушиваться к цветку, наверное он ненормальный? Так посчитали все звери. Но Хортону все равно. Он считает своим долгом спасти население цветка от угрозы извне.",
 "f-wd212098": "Человек страдает, когда не получает того, чего хочет. Но еще больше он страдает, когда не может понять, чего он хочет. .. Молодой писатель Дэн влюблен в стриптизершу Элис, хотя не прочь закрутить роман с модным фотографом Анной. В то же время мрачный мачо Ларри становится бойфрендом Анны, однако встречается и с Элис. И никто из них не способен разобраться в своих чувствах и окончательно определиться, с кем же он желает остаться. Отношения внутри любовного четырехугольника постепенно накаляются, бросая героев в пучину страстей и неумолимо приближая их к неожиданной, парадоксальной развязке…",
 "f-wd623443": "Чтобы отвлечь внимание общественности от сексуального скандала, связанного с президентом США, срочно вызывают специалиста по нештатным ситуациям Конрада Брина. Брин решает инсценировать небольшую войну и, в свою очередь, привлекает известного голливудского продюсера Стенли Мотса. Вдвоем они организуют шоу в мировом масштабе с истинно голливудским размахом! Ну не мог Стенли Мотс упустить этот редкий шанс удовлетворения своих профессиональных амбиций!",
 "f-wd159870": "Вьетнамский ветеран Джон Рэмбо ведет уединенный образ жизни на окраине Бангкока. Уставший от борьбы и кровопролития, скрываясь от проблем, он селится в небольшом доме у реки и проводит дни, ремонтируя старые лодки и катера. Однако судьба вновь заставляет его взяться за оружие. Собрав отряд из пяти наемников, Рэмбо встает на защиту жителей тайской деревни и американских миссионеров, которых захватили в заложники бирманские боевики.",
 "f-wd176826": "Власть президента Уганды Иди Амина и его смелые решения сперва очаровали шотландского медика Гарригана, ставшего личным врачом диктатора. Но жестокий режим и кровавые преступления президента изменили отношение Гарригана к своему кумиру и он, всеми силами, пытается повлиять на проиcходящее.",
 "f-wd7765993": "Всемирный любимчик со дна океана Губка Боб Квадратные Штаны должен спасти свой глубоководный мир, но для этого ему и его друзьям придётся выбраться на сушу и оказаться в нашем.",
 "f-wd1253366": "Гаргамель создаёт Крепыша и Занозу, как две капли воды похожую на смурфиков злобную парочку, надеясь всё-таки обрести магическую силу. Когда он узнаёт, что лишь настоящий смурф может дать ему то, что он хочет, и лишь Смурфетта способна превратить Крепыша и Занозу в настоящих смурфов, Гаргамель похищает Смурфетту и берёт её с собой в Париж, планируя сделать её своей прислужницей. Но смурфики — Папа, Растяпа, Ворчун, Красавчик — и их друзья из Нью-Йорка этого так не оставят.",
 "f-wd647665": "В дикие, девственные леса Африки с небес падает бутылка «Кока-колы». Здесь же обитает по-детски невинное племя бушменов. Вокруг столкновения двух цивилизаций происходит масса комедийных моментов.",
 "f-wd1345920": "Дядюшка Римус рассказывает свои забавные истории о Братце Кролике маленькому Джонни,  чтобы помочь ему справиться с разводом его родителей и новой жизнью на плантации.",
 "f-wd2907178": "После того как все в ее жизни разваливается на части, в том числе и брак с богатым бизнесменом, светская жительница Нью-Йорка Жасмин переезжает в скромную квартиру сестры в Сан-Франциско, чтобы попытаться взять себя в руки и жить дальше.",
 "f-wd16692754": "Любовь под нескончаемым огнем противника, дружба с Элеонорой Рузвельт, выступление на конференции, повлиявшее на исход Второй мировой войны, желание жить и страх потерять любимого человека - справится ли со всем этим хрупкая женщина?  Это реальная история Людмилы Павличенко - легендарной женщины-снайпера. Солдаты шли в бой с ее именем на устах, а враги устроили на нее охоту. На поле битвы она видела смерть и страдания, но самым серьезным испытанием для нее стала любовь, которую у нее могла забрать война...",
 "f-wd1169942": "Взяв практически анекдотическую жизненную ситуацию о том, как степной монгол поехал в город за средствами предохранения, так как по закону он не имел права иметь больше трех детей, режиссеру удалось создать произведение искусства высочайшей пробы, насыщенное добротой, человечностью и состраданием, проповедующее терпимость и понимание между народами без единой фальшивой ноты.",
 "f-wd2368678": "Молодые работники клуба готовятся к встрече Нового года. Директор клуба Огурцов, бюрократ и невежа, активно вмешивается в подготовку концерта, требуя убрать из программы все остроумные и талантливые выступления. Организаторы вечера в отчаянии. Но молодость, увлечённость, желание и умение веселиться помогают «обезвредить» Огурцова...",
 "f-wd339467": "В стремлении сотворить Новый мир — холодный и практичный, где чёткость линий призвана заменить эмоции, а северный ветер должен остудить людские души, Снежная королева избавляется от всех представителей творческих профессий. Маленькой и смелой Герде, отправившейся в опасное путешествие, чтобы спасти своего брата Кая, предстоит столкнуться с этим холодным миром Снежной королевы. Преодолевая все сложности и преграды на пути к своей цели, Герда не только обретает семью, но и веру в себя, находит поддержку новых друзей.",
 "f-wd914190": "В результате незапланированного ядерного взрыва на американской военной базе погибла большая часть населения. Кругом выжженные мёртвые пространства, опустевшие города. Но в катакомбах и подвалах люди, среди которых – и дети, пытаются как‑то наладить свой быт – и им это отчасти удаётся. Главный герой фильма – учёный Ларсен пытается понять причины происшедшего и найти духовную точку опоры, чтобы обрести надежду на выживание…",
 "f-wd3270392": "1917 год — канун Великой Октябрьской социалистической революции. Из Финляндии в Россию возвращается В. И. Ленин. ЦК РСДРП(б) под руководством вождя мирового пролетариата подготавливает план вооружённого восстания в Петрограде...",
 "f-wd620231": "Основа сюжета - старинный сказочный мотив о трудолюбивой Золушке, злой мачехе и ленивых сестрах. Разумеется, Шварцем переработанный и оживленный до уровня комедии, в которой есть и просто юмор, и злая сатира. До сих пор этот нежный и добрый фильм продолжает радовать и удивлять больших и маленьких.",
 "f-wd17512617": "Во время геноцида армян в 1915 году Назарет Манукян теряет семью. Спустя годы он случайно узнает, что его дочки-близнецы, возможно, спаслись. Назарет отправляется на их поиски и доходит из родной деревни Мардин в пустыню Месопотамии, а потом в Новый Свет — в Гавану и Северную Дакоту.",
 "f-wd1634714": "История о трех поколениях семьи потомственных рабочих-судостроителей. Самым сложным характером наделен Алексей: ушел из семьи, потерял профессию, любимую девушку, но все же нашел силы вернуть свое счастье.",
 "f-wd2369228": "Начало 30-х годов. Дальний Восток. В центре фильма — борьба сибиряков против диверсантов-самураев, пытающихся сорвать строительство форпоста обороны у восточных границ СССР.",
 "f-wd2117834": "О событиях первой мировой войны — августа 1914, заставшего Ленина в Польше (местечко Поронино).",
 "f-wd4156475": "Продавщица музыкального магазина знакомится со студентом консерватории, мечтающим стать композитором. В нем девушка находит родственную душу - дело в том, что сама она спит и видит себя артисткой. Однако намечающийся творческий союз вызывает неодобрение директора магазина, который боится потерять лучшую работницу.",
 "f-wd4449955": "Сюжет фильма основан на реальных событиях, произошедших в 1959-м году. В 2012-м году группа американских студентов, получив грант, отправляется на уральские горы, следуя тем же маршрутом, что и группа Дятлова, чтобы попытаться восстановить картину и разгадать причину таинственной, мистической и до сих пор не разгаданной гибели советских лыжников.",
 "f-wd4382272": "Для того, чтобы провернуть очередную спекуляцию, банкир Орнано продает свой дом и на время покидает город. Его жена посылает возлюбленному записку с сообщением о том, что в доме находятся три миллиона.  Записка попадает к авантюристу Каскарилье, но первым в эту ночь в дом пробирается воришка Тапиока, создавая весьма благоприятную для своего конкурента ситуацию. И тут в доме, неожиданно для всех, появляется банкир...",
 "f-wd7598540": "Фильм рассказывает о возвращении в Россию после лечения князя Льва Николаевича Мышкина, его появлении в доме Епанчиных и знакомстве с необыкновенной женщиной Настасьей Филипповной, чей облик с первой секунды поражает князя.",
 "f-wd29382552": "Молодая женщина по пути на свидание к арестованному мужу встречает различных героев своего времени: от полицейских и правозащитников до проституток и бродяг.",
 "f-wd734048": "В поисках вдохновения и новых тем известный столичный писатель отправляется в провинцию. Неожиданно для себя он обнаруживает, что здесь люди живут совсем иначе, чем в привычном ему мире. Став невольным свидетелем подлинной любовной драмы, герой вдруг понимает, что в его жизни и творчестве не хватает самого главного.",
 "f-wd252072": "Героиня фильма - Рита вынуждена скрываться; ее друг Алеша исчез, проиграв в рулетку чужие деньги. Ее спасает и прячет у себя глухая танцовщица ночного клуба Яя, живущая единственной мечтой - накопить денег и уехать в некую сказочную «страну глухих» где живут только глухие люди и поэтому царит добро и справедливость. Неожиданно девушки оказываются в центре жестокого столкновения двух кланов мафии, глухих и слышащих...",
 "f-wd28667926": "Майкл, талантливый аферист, собирает команду людей с паранормальными способностями, чтобы ограбить казино. Однако все идет не по плану, и герои оказываются в смертельной опасности. Чтобы спасти их, Майклу придется действовать за гранью реальности — в загадочном мире подсознания, откуда проистекают сверхспособности его друзей.",
 "f-wd97177450": "Героическая история о пожарных и спасателях. То, что обычно называют подвигом, для них — привычные будни, если только можно привыкнуть к смертельной опасности и предельному риску. Когда людям, попавшим в беду, кажется, что помощи ждать неоткуда, на выручку приходят спасатели, чтобы встать на пути беспощадной стихии.",
 "f-wd1634934": "Трое друзей из Москвы живут «дикарями» в замечательном месте с песчаным пляжем, пресной водой, тенью и дровами у самого моря. Отдыхают. Внезапно приезжают две незнакомки и заявляют, что это их старое место. Более того, они доказывают свое первенство, выкопав бутылку с письмом. Но уезжать ребята отказываются. Дамы же от своего места отказываться тоже не собираются и ставят палатку. Начинается тихая война, перерастающая со временем в любовь. Один из тех фильмов, которые можно пересматривать не один раз.",
 "f-wd1963834": "Маленький губернский городок на юге России, 20-е годы XX века. Кончилась гражданская война, но до полной победы большевиков ещё далеко. Пятеро друзей, бывших бойцов Красной Армии, а ныне — чекистов, готовят к отправке в Москву ценный груз — золото, необходимое для закупки продовольствия. Первоначальный план идёт прахом, когда в комнате одного из них — Егора Шилова — находят изуродованный труп. Сарычев решает первым же поездом отправить золото тайно и с минимальной охраной...",
 "f-wd2333940": "Пять веков славянские народы Балканского полуострова находились под игом османских турок. В 1877 году Россия объявляет войну Турции. Под руководством талантливых генералов в суровых природных условиях русские и болгарские воины одерживают ряд крупных побед. Разбив врага под Плевной, русско-болгарская армия движется на Стамбул.  И хотя Россию под нажимом западных государств, боящихся ее усиления, вынуждают прекратить войну, благородная цель достигнута - болгарские народы освободились от турецкого ига.",
 "f-wd2474366": "Русский супер-агент - строго засекреченный шпион Шура Осечкин, он же штандартенфюрер СС Олаф Шуренберг, самоотверженно и нахально ведет подрывную деятельность в ставке Гитлера. Войне скоро конец, и это уже понятно всем, кроме фанатичного фюрера и подозрительного Мюллера. Простые труженики Рейха давно махнули на все рукой, пустились в отрыв и бесшабашно тусуются по клубам. Шуренберг скучает по дому и выращивает помидоры в тайной теплице возле своего дома на 007-Штрассе. Очередное задание Центра сваливается на него прямо с неба - вместе с новой помощницей, очаровательной и сексапильной радисткой Зиной, мечтой каждого мужчины. С такой боевой подругой недолго и про войну забыть! Но долг превыше всего: прежде чем вернуться на Родину и зажить счастливо вместе, супер-агентам Шуренбергу и Зине предстоит провернуть одну, последнюю и очень важную операцию...",
 "f-wd969646": "Фильм о любви с конкретным историческим фоном и точной материальной средой. Время действия: февраль 1917 — июль 1918.",
 "f-wd1057951": "Вечный любовный треугольник: спустя годы Виктор выясняет, что у его покойной жены, возможно, были отношения с Олегом — его старинным приятелем. Выяснение отношений с Олегом заходит в тупик. Внутренние переживания и искания главного героя усугубляются тем, что волею обстоятельств Виктор втянут в международные дипломатические интриги.",
 "f-wd57923356": "В недалёком будущем что-то произошло. Связь с большей частью населённых пунктов Земли оборвалась. Космонавты передали с орбиты, что видят сверху небольшое пятно в Восточной Европе, по своим очертаниям напоминающее круг. То, что военные находят за границей этого круга, шокирует. В магазинах, в автомобилях, на дорогах, в зданиях больниц и вокзалов, повсюду — следы столкновений. Кто или что уничтожает всё живое? И как долго продержится последний аванпост человечества?",
 "f-wd1967184": "Выпускник военного училища младший лейтенант Ивлев попал на фронт в последний день войны. Он мечтал о подвигах, о боях на передовой - а вместо этого получил «скучнейшее» задание: доставить в тыловой госпиталь раненого советского солдата и беременную немку. Казалось бы чего проще. Однако события ближайших часов заставят Ивлева пережить такое, что он навсегда простится с мальчишескими представлениями о войне...",
 "f-wd111962910": "Картина расскажет о пути владельца похоронного бизнеса Джеремайя О'Кифа  и деловитого адвоката Уилли Гэри к успеху.",
 "f-wd269331": "В Гарлеме неграмотной девушке-подростку, страдающей избыточным весом и, ко всему прочему, беременной вторым ребенком, предлагают вступить в альтернативную школу в надежде, что ее жизнь кардинально изменится…",
 "f-wd15427353": "Фильм рассказывает историю 17-летнего паренька по имени Джей Кавендиш, который путешествует по всей американской границе в поисках девушки, которую он любит. В опасном приключении его сопровождает таинственный путешественник Сайлас.",
 "f-wd112909147": "История об исполнении желаний подростка, игравшего в Gran Turismo, чьи игровые навыки позволили выиграть серию соревнований Nissan, чтобы стать настоящим профессиональным гонщиком. Основано на реальной истории.",
 "f-wd28494346": "Калифорния, пустыня Мохаве, 1998 год. Сэм, продавец, путешествует по нескольким населенным зонам калифорнийской пустыни в поисках клиентов, но все кажется пустынным. Более того, его жена не отвечает на звонки. Словно все избегают его. Когда машина ломается, Сэм становится узником пустой, враждебной среды. В одиночестве и без контакта с людьми, в течение нескольких дней, он постоянно слушает ток-шоу на единственной местной радиостанции. Хозяин, человек по имени Эдди, принимает звонки от слушателей, которые разделяют их мысли о убийце-педофиле, действующим в этом районе. В это же время, Сэма начинают преследовать странные угрозы, которые он получает на свой пейджер. Постепенно люди начинают появляться и пытаться убить его. Действительно ли он убийца, которого они ищут, или его заставляют стать таким?",
 "f-wd58894738": "В переломный момент в истории Католической церкви папа Бенедикт XVI завязывает дружбу с будущим папой Франциском. Основано на реальных событиях.",
 "f-wd1201853": "Могучему Тору предстоит вновь сразиться за восстановление порядка в галактике, встретившись лицом к лицу с древней инопланетной расой, ведомой злодеем Малекитом, который жаждет установить в девяти мирах власть тьмы. Столкнувшись с врагом, более могущественным, чем сам Один и всё воинство Асгарда, Тор должен собрать силы для решающей битвы. Его ждёт опасное путешествие и долгожданная встреча со своей земной возлюбленной Джейн Фостер. Сможет ли Тор рискнуть самым дорогим, чтобы не дать тьме воцариться на просторах вселенной?",
 "f-wd108196081": "16-летняя Маша учится в обычной киевской школе в 11-А классе. Не чувствовать себя странно и отстраненно в коллективе ей помогают близкие друзья Яна и Сеня. Кроме будущих экзаменов выйти из зоны комфорта Машу заставляет влюбленность в одноклассника Сашу. Она понимает, если не решишься спросить – никогда не узнаешь, взаимно ли это.",
 "f-wd532264": "Молодая длинноногая танцовщица Номи отчаянно пытается добиться успеха в Лас-Вегасе и проникнуть в блистающий мир ярких огней, блеска и света шоу — сцены. Чтобы удержаться «на плаву», она соглашается на единственно возможную работу — стриптиз, пока ей не удается вытянуть свой счастливый билет — познакомиться с королевой сцены Лас-Вегаса Кристал.",
 "f-wd104902967": "Девушка-подросток занимается гимнастикой, всячески пытается угодить матери и достичь высот в спорте. Однажды она находит брошенное, как она думала, птичье яйцо и решает не дать ему погибнуть. Находка достигает невероятных размеров, и вскоре из яйца вылупляется неведомая зверушка. Теперь всему семейству придется несладко.",
 "f-wd16954098": "История Эллис Лэйси, которая неохотно покидает свою родную ирландскую деревню и отправляется на поиски работы в Америку. В итоге она поселяется в Бруклине, постепенно излечивается от ностальгии и начинает наслаждаться воздухом свободы. Ко всему прочему Эллис влюбляется, но трагические новости с родины заставляют ее вернуться в Ирландию, где она встречает другого мужчину и в результате вынуждена делать нелегкий выбор.",
 "f-wd29021224": "Детективы Майк и Маркус снова в деле! Правда, их отстраняют от всех операций, но разве отчаянных друзей когда-нибудь что-либо останавливало? Ведь на этот раз на Майка открывает охоту некто из его прошлой жизни. Так что парням придётся отжечь по полной!",
 "f-wd17436508": "Первая волна оставила за собой мглу. От второй успели убежать только самые везучие. Но едва ли можно назвать везучими тех, кто уцелел после третьей. А четвертая волна стерла все человеческие законы, взамен же установила свой, один-единственный: хочешь жить — не верь никому. И вот уже накатывает пятая волна…",
 "f-wd15713892": "История о сироте, который попал в волшебную Нетландию, где его поджидали опасные приключения. Там он понял, что его судьба – стать героем, который навсегда останется известен под именем Питер Пэн.",
 "f-wd16354845": "А вдруг ты тоже спецагент, обладающий уникальной боевой подготовкой и сверхинтеллектом? Но просто ты забыл об этом… Как Майк Хоуэлл, лоботряс из супермаркета, который безмятежно читает комиксы и курит дурь пока славное прошлое не настигает его. И обдолбанный агент N1 становится мишенью N1.",
 "f-wd110140881": "1945 год. В Нюрнберге начинает работу Международный военный трибунал. На суд, который впоследствии назовут Процессом Века, съезжается огромное количество людей со всего мира: город переполнен журналистами, адвокатами, переводчиками, свидетелями и множеством участников и сотрудников процесса. Среди тех, кто приезжает в Нюрнберг работать на Процессе — Игорь Волгин. Он молод, но прошёл войну, имеет награды, владеет несколькими иностранными языками. Волгину предстоит быть переводчиком в составе советской делегации под руководством полковника Мигачева. Однажды на улице Нюрнберга Волгин встречает юную русскую девушку Лену. Их зарождающееся чувство пройдёт через множество испытаний, но любовь — это единственное, что во все времена спасало мир от расчеловечивания...",
 "f-wd24934510": "Вместо десерта на ужин семейство Бобровых получило… метеорит. Настоящий, большой, из космоса. Благодаря ему Бобровы вдруг приобретают немыслимые сверхспособности. Дед становится бессмертным, а отец теперь может телепортироваться. Сын начинает понимать собачий язык, а его сёстры получают суперсилу, возможность летать и быть невидимой. Единственное ограничение - способности действуют только когда вся семейка в сборе.  Короче, у заурядной, среднестатистической ячейки общества появляется шанс превратиться в отряд настоящих супергероев. Вот только вместо того, чтобы спасать мир, они решают ограбить ближайший банк…",
 "f-wd602389": "Ученые — астронавты возвращаются на Землю после успешной экспедиции на Марс. Однако с различными пробами на корабль проникает нечто ужасное, что угрожает жизни землян. Один из участников полета превращается в неземную тварь и жаждет наплодить себе подобных. Ему необходимо встретиться с другой особью, которую изучают в лаборатории. Этого не должно произойти…",
 "f-wd3346699": "История эротических переживаний женщины по имени Джо от рождения до пятидесятилетия. Холодным зимним утром Селигман, немолодой одинокий холостяк, натыкается в переулке на Джо, избитую и находящуюся в полубессознательном состоянии. Доставив женщину домой, он рассматривает ее раны и задается вопросом, как дошла она до такой жизни. Джо рассказывает Селигману историю своей бурной молодости.",
 "f-wd114819": "Планета Арракис, также известная под названием Дюна, год 10191. Арена борьбы между злом и благородством, мир тончайших и опаснейших интриг. Гигантские песчаные черви длиной в целую милю сторожат бесценное сокровище — меланжевую пряность, позволяющую путешествовать сквозь пространство и время. Тот, кто контролирует пряность, контролирует Вселенную.\r Народ Дюны ожидает пришествия Мессии, который поведет их на священную войну против династии злобных Харконненов. И Мессия является. Им становится юный Пол Атрейдес, сын герцога Лито, предательски убитого Харконненами с одобрения Императора. Полу предстоит великая миссия, которая навсегда изменит судьбу всей галактической империи.",
 "f-wd15929448": "События развиваются спустя 2 года после начала пятилетней миссии.  Экипаж звездного корабля «Энтерпрайз», во главе с капитаном Джеймсом Т. Кирком, были атакованы могущественной и опасной волной неизвестных пришельцев, которые уничтожают корабль, оставляя их без всего на новой неизведанной планете, где они оказываются в конфликте с новым безжалостным врагом.",
 "f-wd11220194": "Численность генетически модифицированных обезьян, возглавляемых Цезарем, продолжает увеличиваться, но обезьянам угрожают люди, которым удалось выжить во время ужасной эпидемии десятилетней давности. Поначалу между соперниками устанавливается хрупкий мир, но он оказывается недолговечным. Обезьяны и люди находятся на грани войны, в ходе которой станет понятно, кто из них в будущем станет безраздельно править планетой.",
 "f-wd156394": "Сексапильный Ник Маршал, плейбой из Чикаго, должен получить продвижение по службе. Но в агентстве появляется Дарси Макгуайр, которая становится руководителем Ника. Во время проработки задания новой начальницы с Ником происходит несчастный случай, после которого он открывает в себе уникальный дар: читать женские мысли.Эта способность даёт Нику шанс вернуть себе утраченные позиции в агентстве.И когда реализация коварного плана была в полном разгаре, одно непредвиденное обстоятельство свело всё на нет. Имя этому обстоятельству — любовь.",
 "f-wd464042": "Команда исследователей отправляется на поиски затерянных индейских племен в самое сердце таинственных джунглей Амазонки. Наслаждаясь пейзажами великой реки, они не подозревают, что их проводник — сумасшедший охотник, помешавшийся на идее поймать гигантскую змею.  Никто не верит его рассказам о мистическом хищнике, пока не появляется первая жертва, и их путешествие превращается в борьбу за выживание. Анаконда не ждёт охотников, она сама — охотник.",
 "f-wd23016495": "Группа пляжных спасателей работает на побережье Тихого океана. Они всегда находятся на своём посту и охраняют отдыхающих от несчастных случаев на воде. Главный герой, опытный спасатель Митч Бьюкеннон, и его молодой коллега Мэтт Броди случайно узнают, что их пляж находится под угрозой исчезновения. Большая нефтяная компания собирается разрушить побережье, преследуя личные интересы руководства, крепко завязанные на финансах.",
 "f-wd115760": "Пейшинс Филипс работает дизайнером в крупной косметической компании, которая готовится выпустить на рынок новый продукт, замедляющий старение. Но у этой революционной новинки есть существенный недостаток, который компания тщательно скрывает и о котором случайно узнает Пэйшинс. Дальнейшие события меняют ее жизнь самым невероятным образом…",
 "f-wd645597": "В третьем тысячелетии мир переменился. Климат, народы — все перевернулось… Земля превратилась в ядовитую, выжженную пустыню, которую стали называть «Проклятая земля». Миллионы людей сосредоточились в нескольких огромных городах, на улицах которых царили хаос и преступники. Система правосудия не смогла справиться с анархией, и был создан новый порядок — элитные подразделения, которые сами задерживали, судили, выносили приговор и приводили его в исполнение. Их называли Судьями.",
 "f-wd14522493": "Более тысячи лет назад измученная душа скиталась по Земле, полубог, получеловек - Геракл - могучий сын царя богов Зевса, совершив все 12 подвигов, потерял семью и теперь находит утешение только в кровавых битвах. За эти годы он собирает вокруг себя шестерых таких же потерянных воинов, единственным смыслом жизни для которых стали сражения и присутствие смертельной опасности. Эти мужчины и женщина никогда не задают вопрос, где, почему или с кем они идут сражаться; только, сколько им заплатят. Зная это, фракийский царь Котис нанимает этих воинов, чтобы они обучили его солдат и сделали из них самую сильную и великую армию всех времен.",
 "f-wd51803319": "Двенадцатилетний Зейн не может точно ответить на вопрос, сколько у него братьев и сестёр, но уверен, что детей в его семье должно было быть меньше. Несмотря на юный возраст, Зейн нелегально работает, следит за младшими, помогает старшим, ищет деньги и документы на эмиграцию в Швецию. Он смотрит на мир с нескрываемой ненавистью. Ему есть что ненавидеть. Дети на улицах Бейрута попрошайничают, едят посыпанный сахаром лёд и чипсы, девочек как можно раньше продают замуж, сам он вынужден есть что попало, спать, где придётся, и самое главное — он только что получил пятилетний срок. В тюрьме Зейн подаёт в суд на родителей. За то, что они дали ему жизнь.",
 "f-wd1129308": "На скотном дворе животные ведут двойную жизнь: пока фермер рядом, они ведут себя как обычные домашние животные, но стоит ему уйти, как коровы, свиньи, овцы и другие обитатели начинают петь, танцевать и устраивать шумные вечеринки. Больше всех любит веселиться молодой бычок Отис, который не слишком задумывается о будущем и ответственности. Однако его беззаботная жизнь меняется после трагедии, заставившей его повзрослеть и занять место своего отца Бена — уважаемого защитника скотного двора. Теперь Отису предстоит научиться заботиться о других и противостоять опасным койотам, угрожающим всему хозяйству.",
 "f-wd4346544": "Братья Папашвили, приехав в аэропорт, откуда один из них должен улететь в Израиль, захотели выпить шампанское. Захотели и выпили. И поэтому улетел не хормейстер детского хора Яков, а очень похожий на него брат - таксист Мераб. О его мытарствах-приключениях, выходящих за всякие пределы воображения, и рассказывает эта комедия с грустинкой. Евреи его принимают за агента КГБ, работники советского торгпредства за провокатора, а вернуться домой официально он не может.",
 "f-wd55659358": "Русский князь Михаил и юная Тиче - дети разных народов, разных миров и разных богов. Любовь молодого воителя и ведьмы-ламии кажется невозможной, но преодолевает все запреты, запуская маховик рока. Отныне только от Михаила зависит будущее родной Пармы, древних суровых земель, напоенных чудодейственной мощью кровавых языческих богов. Здесь сталкиваются герои и призраки, князья и шаманы, вогулы и московиты. Здесь расстаться с жизнью - не так страшно, как выбрать между долгом, верностью братству и любовью к единственной женщине на свете.",
 "f-wd4339526": "Экранизация знаменитой повести Льва Толстого погружает нас в бурный мир страстей и борьбы с ними, захлестнувший незаурядного и сильного человека — князя Степана Касатского…",
 "f-wd4214115": "Когда в детском саду объявили карантин, оказалось, что пятилетнюю Машу не у кого оставить, все заняты неотложными делами. Даже прабабушка и прадедушка тоже работают. Поэтому Маша будет жить у родственников, друзей, коллег и случайных знакомых, а заодно, быть может, узнает много полезного, интересного и увлекательного.",
 "f-wd116465881": "Год спустя после того, как майор Гром поймал Чумного Доктора. Санкт-Петербург оправился от потрясений, Сергей Разумовский оказался в психиатрической лечебнице, а Игорь Гром стал главной знаменитостью в городе. Жизнь майора Грома идеальна: днём он ловит преступников вместе с напарником Димой Дубиным, а вечера проводит в компании журналистки Юлии Пчёлкиной. Полную идиллию прерывает появление в городе таинственного злодея, называющего себя Призраком. Он предлагает Грому сыграть в опасную игру, ставка в которой — жизни обычных людей.",
 "f-wd132256832": "Хиг - гражданский пилот, живущий в постапокалиптическом Колорадо на заброшенной авиабазе вместе со своей собакой Джаспером и ворчливым, но верным рейнджером Бэнгли. Их уединённую жизнь нарушает неожиданное радиосообщение, которое пробуждает в Хиге надежду на существование других выживших. В поисках источника сигнала Хиг отправляется в опасное путешествие на своём старом самолете. Его путь пролегает через опустошённые города, дикие леса и враждебные территории.",
 "f-wd466792": "История человека, который после несчастного случая обнаружил в себе выдающиеся психофизические способности. Он пытается найти своё место в мире, используя этот необычный дар с пользой для людей.",
 "f-wd50280803": "Это история непослушной девочки Саши, родители которой неосмотрительно пожелали себе на Новый год, чтобы у них вместо Саши появилась хорошая девочка. Не успели пробить праздничные куранты, как на пороге появилась чужая хорошая девочка, а Саша сказочным образом перенеслась в волшебную Страну хороших деточек на перевоспитание. В этой стране правит строгая королева и ее еще более строгий полномочный представитель, а жизнь подчинена строгим правилам. Чтобы вернуться домой к родителям, Саше придется пройти через невероятные приключения и преодолеть множество испытаний, в чем ей помогут верные друзья — кот Багет и пес Балбес.",
 "f-wd15270454": "Группа молодых людей собирается на главную тусовку лета. Как и полагается, подготовка идёт полным ходом, но никто не догадывается, что судьба готовит им совершенно другую программу на афтепати. Оказавшись в эпицентре зомбоапокалипсиса, друзья обнаруживают, что «ходячие» охотятся только за теми, кто испытывает страх…",
 "f-wd949879": "Много лет назад игривый малыш спрятался в мешке Санта-Клауса и отправился на далёкий Северный Полюс.Очутившись среди эльфов, бедный мальчуган был усыновлён одним из них, получил имя Бадди и спустя годы пытается утвердиться в сложном мире волшебных пигмеев. Одна проблема — слишком уж он высок и заметен, чтобы стать настоящим эльфом…",
 "f-wd4289564": "Маленький провинциальный городок. Скука, тупость, злоба обывателей… Скромный учитель гимназии Передонов мечтает о повышении по службе и переезде в столицу. Постепенно мечта становится навязчивой идеей. Троюродная сестра Передонова Варвара, мечтающая выйти за него замуж, пишет письма с обещаниями о приглашении в Санкт-Петербург от имени столичной княгини. Но мечтам учителя не суждено сбыться: став жертвой собственного безумия, он убивает своего дружка и ненавистную Варвару…",
 "f-wd127012906": "XVII век. Чхатрапати Шиваджи Махарадж, основатель государства маратхов, бросает вызов тюркско-мусульманскому господству. Его старший сын Чхатрапати Самбхаджи Махарадж с мужеством и решимостью продолжает дело отца и противостоит правителю Аурангзебу.",
 "f-wd124254266": "Город Чандери снова населяют призраки — на этот раз ужасающее безголовое существо похищает женщин. Вики и его друзьям предстоит спасти свой город и близких.",
 "f-wd118641054": "Лили Блум, женщина, которая преодолела травмирующее детство, чтобы начать новую жизнь в Бостоне и осуществить мечту всей жизни - открыть её собственный бизнес. Случайная встреча с очаровательным нейрохирургом Райлом Кинкейдом вызывает интенсивную связь, но когда они глубоко влюбляются друг в друга, Лили начинает видеть стороны Райла, которые напоминают ей об отношениях её родителей.",
 "f-wd118175825": "1965-ый год. На музыкальном фестивале в Ньюпорте производит фурор выступление молодого Боба Дилана.",
 "f-wd21152182": "Адаптация одноименного романа индийского писателя Беньямина, основанного на реальных событиях. Об индийском эмигранте Наджибе Мухаммаде, пропавшем без вести в Саудовской Аравии и чьей мечтой было работать в странах Персидского залива и заработать достаточно денег, чтобы отправить их домой. Но после череды происшествий главный герой становится рабом-пастухом коз посреди саудовской пустыни. Наконец, Наджиб придумывает опасный план побега из пустынной тюрьмы.",
 "f-wd125678238": "Молодая женщина, совсем недавно потерявшая мужа и еще сильно переживающая его трагическую смерть, вынуждена встать на защиту своих детей от опасного и таинственного незнакомца, который внезапно появляется на пороге их дома.",
 "f-wd126537613": "Студент первого курса элитного колледжа, выбранный мишенью из-за своей касты, борется с жестокими хулиганами и смертельными угрозами, чтобы защитить своё достоинство и запретную любовь.",
 "f-wd112665700": "Семь лет спустя, после завершения расследования, связанного с Виджаем Сальгаонкаром и его семьей, серия неожиданных событий разворачивается, выдвигая на передний план истину, способную радикально изменить жизнь Сальгаонкаров. Стоит лицом к лицу с этим новым вызовом, сможет ли Виджай на этот раз обеспечить защиту своей семье?",
 "f-wd1411238": "Это история простой женщины Радхи, которая была брошена своим мужем. Тот лишился обеих рук во время инцидента в поле. Уйдя из дому, он оставил жену с двумя маленькими детьми на руках. Старший сын рос хорошим и усердным мальчиком, младший же сын был полной противоположностью старшего. На фоне материнской любви к обоим сыновьям развивается история выживания одинокой матери Радхи. Когда Радха только вышла замуж, ее свекровь заняла пятьсот рупий у местного ростовщика Сукхилала. Согласно договора,который свекровь подписала не читая, взамен процентов она должна была отдавать четверть будущего урожая. Пользуясь ее безграмотностью, Сукхилал вместо одной четверти в договоре прописал три четверти. Когда все выплыло наружу, деревенский сход принял сторону ростовщика. Таким образом Радхз осталась без средств к существованию.",
 "f-wd1094839": "Санжай Мехра - ученый, одержимый идеей вступить в контакт с неземной жизнью. Наконец он создает компьютер, способный отправлять послания в космос. Его мечта становится реальностью, когда, в ответ на сигнал компьютера, в небе появляется космический корабль.  Но прежде чем Санжай смог насладиться своим успехом, с ним и его женой Соней происходит автокатастрофа, в результате которой Санжай умирает. Сын Санжая - Рохит - умственно отсталый ребенок, чья жизнь превращается в муку и пытку. Его единственный друг - Ниша, чье сострадание притягивает ее к Рохиту.  Однажды Рохит находит старый компьютер своего отца и Просит Нишу помочь ему. Они оба поражаются картинам и конструкциям, которые появляются на мониторе и продолжают экспериментировать с машиной, не представляя себе последствий этого.",
 "f-wd622376": "Взрослый Апу, став сиротой, живет в жалкой комнатке в Калькутте и стремится стать писателем. Его друг Пулу приглашает его на свадьбу своей сестры Апарны в небольшую бенгальскую деревню. Однако счастье невесты длится недолго – жених оказывается сумасшедшим. А если она не выйдет замуж в назначенный час, будет навеки опозорена. В знак протеста сбитый с толку Апу женится на девушке и забирает молодую жену с собой в город. Через год его жена умрет при родах, оставив Апу сына, которого он поначалу не хочет видеть. Только через пять лет его друг находит его и уговаривает взять на себя заботу о ребенке…",
 "f-wd905417": "Актриса столичного театра Ниша влюблена в режиссера Рахула. Но Рахул не верит в сильные чувства и для него загадка — как двое могут в течение всей жизни прожить вместе. Рахул грезит о девушке своих снов по имени Майя, не подозревая, что его принцесса живет совсем рядом с ним и что они постоянно сталкиваются (не зная об этом) друг с другом. Движимый своей мечтой, он хочет поставить спектакль о Майе. Когда Ниша травмирует ногу и уезжает на лечение в Лондон, в театре появляется новая актриса Пуджа. После близкого знакомства с ней к Рахулу впервые приходит настоящее чувство — любовь. Пуджа отвечает ему взаимностью, однако у нее есть жених, ее друг детства, с которым она не готова расстаться. А тут еще и влюбленная Ниша возвращается с надеждой завоевать Рахула. Как в дальнейшем будут развиваться отношения в этих любовных треугольниках?",
 "f-wd1519550": "На экране старая как мир история о двух сестрах-близнецах, разлученных в раннем детстве. Гита, похищенная цыганами, стала бродячей танцовщицей. Зита, воспитанная богатым дядюшкой, — богатой наследницей. Но потом, пройдя через массу забавных приключений и недоразумений, они встретились, чтобы к финалу каждая обрела долгожданное счастье и любовь.",
 "f-wd1326725": "У учителя музыки есть единственная, любимая дочь Нандини. Однажды в доме учителя появляется студент Самир, который изучает национальную музыку. Самир селится в доме учителя, который во всем ему помогает. Постепенно между Самиром и Нандини вспыхивают настоящие чувства. Но отец Нандини узнав об этом выгоняет Самира из дома, а дочь вынуждает выйти замуж за другого. После свадьбы проходит какое-то время, супруг Нандини видит, что она страдает и не может забыть Самира. Тогда муж предлагает ей найти его…",
 "f-wd1094828": "Три молодых человека, таких разных и неординарных. С такими непохожими взаимоотношениями с любимыми женщинами. Но в одночасье их судьбы пересекаются самым неожиданным образом…",
 "f-wd16248904": "Сэр Чаудхари выдает дочку замуж по старой семейной традиции-сам найдя для нее достойного жениха. Но у девушки есть возлюбленный Ракеш,с которым она и сбегает из дому. Чаудхари похищает друзей Ракеша и пытается выведать у них местонахождение парочки.Только не учел Чаудхари,что дружба может быть ценнее жизни,а любовь дороже всего на свете.",
 "f-wd852001": "И он и она - родом из небольшого провинциального городка. И его и ее не устраивает серая монотонная жизнь. И они вырываются из своих клеток в поисках счастья. А когда их пути пересекаются, на свет появляется пара Банти и Бабий, величайших мошенников-авантюристов, путешествующих по дорогам страны..",
 "f-wd15747101": "Вира накануне своей свадьбы мечтает вырваться на волю хоть на часок - приготовления к торжеству ей порядком наскучили, и она хочет глотнуть свежего воздуха вдали от кузин и тётушек, которые только и говорят о нарядах и украшениях. Она оказалась не в то время не в том месте, и вся её жизнь перевернулась с ног на голову. А, может быть, и наоборот. Ведь никому неизвестно, где лежит дорога, которая ведёт к судьбе.",
 "f-wd1215405": "Украденную в детстве, Умрао продают в публичный дом в Лакнау, столицу похоти и разврата. Однако, обладающая красотой и острым умом, девушка все же борется за свое счастье и любовь. На своем пути она встречает множество испытаний: обманувшего ее молодого человека Наваба Султана, гибель нового возлюбленного Гаухара Мирзы, неожиданную встречу со своей родной семьей и последующее изгнание из нее... Увенчаются ли боль и разочарования, гнев и страдания героини заслуженным счастьем?!",
 "f-wd2213842": "Судьбы героев переплетаются, но на пути у счастья встают проблемы, с которыми необходимо уметь справляться. Юноша Ашутош борется за любовь своей супруги, которая потеряла память и не узнает его. Таксист Раджу влюбляется в иностранку, которая приехала в Нью-Дели на поиски неверного бойфренда. Лондонский бизнесмен Виней не счастлив в браке и однажды встречает в вагоне метро девушку своей мечты. Светская львица Ккамини объявляет поклонникам, что собирается замуж за вымышленного мужчину, но тут появляется ОН сам. Закоренелый холостяк Шивен разрывает отношения со своей девушкой накануне свадьбы, а молодожены Рам и Пулвати никак не могут отдать друг другу супружеский долг. Времена меняются, и у любви всегда есть шанс.",
 "f-wd43208788": "История факира, влюбившегося в девушку в Париже, а затем случайным образом отправившегося в путешествие по городам Европы. Теперь ему предстоит найти обратный путь к незнакомке, которая так сильно приглянулась его сердцу.",
 "f-wd3413700": "Удачливый бизнесмен в индустрии телесвязи. В его рукаве есть много тузов, он — настоящий современный герой: обаятелен, богат, умен. Но его будущее покрыто мраком: никто не может считаться виновным, пока это не доказано. Но, как ни странно, его судьба — быть виноватым без вины…",
 "f-wd1262452": "Фильм повествует об истории Джая и Адити. Хоть они и являются частью большой и дружной компании молодых людей, но только они двое из этой компании — особенно близки. Постоянно проводят вместе свободное время, общаются по телефону и вообще все делают вместе. Поэтому все вокруг считают, что между ними роман. После окончания колледжа родители Адити решают поженить эту пару, чем шокируют самих молодых людей. Джай и Адити утверждают, что не испытывают чувств друг к другу и жениться не собираются. В качестве доказательства своих слов, они решают подыскать друг другу спутников жизни, которые бы идеально им подходили…",
 "f-wd2066387": "Два сына миллионера: Один крутой бизнесмен, а другой бездельник-ловелас влюбляются в одну и ту же девушку, дочь шофера. Теперь ей предстоит выбор - кому отдать свое сердце.",
 "f-wd5714757": "Чандни и Чандр очень любят друг друга и хотят пожениться. В канун своей помолвки Чандр попадает в сильную бурю и не справившись с управлением попадает в страшную аварию. Машина Чандра падает в реку и его уносит к другому берегу. Происходит это все на границе с Пакистаном. Пакистанская девушка Хенна находит Чандра без чувств, она помогает ему. Постепенно девушке удается поднять на ноги Чандра и он в знак своей признательности решает жениться на ней. Ведь Чандр потерял память и даже не подозревает, что в Индии его ждет любимая девушка.",
 "f-wd806318": "Фильм рассказывает историю Кальяни, красивой молодой женщины, которая отбывает заключение в женской тюрьме по обвинению в преднамеренном убийстве. В её сознании переплелись любовь, ненависть и человечность. Доктор Дивендра, благородный молодой человек, работает доктором в той же тюрьме. Встретив Кальяни, Дивендра влюбляется в неё настолько, что, невзирая на её прошлое, делает ей предложение.",
 "f-wd7262814": "Это — история Абхая и Алиши — Абхай — тормозной, неуклюжий, социально оспариваемый неудачник в очках и Алиша — воплощение красоты, для которой любой человек охотно сорвал бы свое сердце! И когда эти два мира сталкиваются, получается: Красота + Глупость = Невозможная Любовь!",
 "f-wd28444714": "Рохан собирается вновь продлить свою историю учебой в заведении, только сегодня его жизнь изменится. Невероятно, но впервые его судьба сводит с Кубком Достоинства, но здесь слава перетекает в руки другого правления. Трудно представить, но конкуренция увеличивается с каждой минутой, соперники становятся все сильнее и отважней, что обязательно приведет к неприятному столкновению. Каждый из противников не просто сильный, он обладает своеобразной силой, которая сможет переломить ход истории. Пробил час, только Рохан не понял, что в его судьбу вмешивается кое-кто другой. Но вскоре, на пути появился противник, который полностью перечеркивает наработанное. Оказывается, он с легкостью и уверенностью исключается с заведения, не понимая, что на этом ему придет конец. Он не собирается сдаваться, да и бороться с такими наглецами нет смысла. История перетекает в новое русло.",
 "f-wd2020253": "В основу сюжета картины положена реальная история перестрелки между полицейскими и гангстерами в Свами Самарнатхе, пригороде Мумбая, который теперь известен как Локандвала. Это случилось в 1992 году, когда засевшие в одной из квартир 6 главарей мафии отстреливались от полицейских в течение 6 часов. Не перестрелка, а настоящее сражение, в котором было задействовано 255 полицейских, возглавляемых полицейским инспектором Кханом, и выпущено 1755 пуль. Во время этой операции Кхан настолько превысил полномочия по зачистке, что попал под внутреннее расследование в своем же департаменте. Перестрелка в Локандвале - это история начинающего бандита Майи и его опытного партнера Дилипа...",
 "f-wd135975525": "После того как серийный убийца Карл Бходжрадж сбегает из тюрьмы и появляется в Мумбаи, инспектор Зенде ставит себе задачу снова поймать хитрого преступника.",
 "f-wd61994951": "Действие фильма происходит в Мумбаи, где полиция продолжает отчаянно бороться с терроризмом. Несмотря на все усилия правительства по ликвидации подполья, боевики постоянно идут на шаг впереди. Три суперполицейских объединяются, чтобы покончить с терроризмом в Мумбаи раз и навсегда.",
 "f-wd102036246": "Джордж стал состоятельным владельцем кинотеатра. Он надеется снять свой собственный фильм и прилагает все возможные усилия для реализации этих амбиций. Завистливые соседи Джорджа начали распространять нелицеприятные слухи, что подрывает и без того слабое здоровье Анджу. Тем временем, полицейские продолжают расследование исчезновения Варуна. На этот раз они установили слежку за Джорджем, полагая, что своими действиями он раскроет тайну убийства. В конце концов, полицейским, работающим под прикрытием, удаётся раздобыть необходимую информацию…",
 "f-wd531340": "Санджай Сингхания — один из самых успешных предпринимателей страны. Калпана — модель, снимающаяся в дешевой рекламе. Вероятность их встречи была равна нулю. Тем не менее, пути их пересеклись, и родилась любовь, которой не суждено было расцвести. Однажды Калпана вступает в конфликт с преступником Гаджини; ценой своей жизни она спасает невинных девочек от гибели. В попытке спасти саму Калпану Санджай получает тяжелейшую травму. Спустя время он ищет преступника, чтобы отомстить. Ситуация осложняется тем, что Санджай теперь страдает амнезией и помнит лишь то, что происходило с ним в последние 15 минут.",
 "f-wd12975794": "Красавица Дия — звезда модельного бизнеса, но в то же время, скромная и порядочная девушка. Устав от домогательств своего партнера по съемкам, она обращается за помощью к звездному бодибилдеру Лингесану. Ее план прост: заменить наглого напарника Джона, сделав из Лингесана звезду. Однако деревянный качок никак не может постичь даже азов актерского мастерства, а потому менеджеру Дии, который тоже хочет помочь девушке, приходит на ум хитрый план.",
 "f-wd1520721": "Адитья — бизнесмен-неудачник. Он несчастен, потому что, его любимая девушка выходит замуж за другого. Ему не хватает мужества вернуться домой, он решает плыть по течению, садится в первый попавшийся поезд, и едет, « куда глаза глядят». Но судьба распоряжается иначе. В поезде он знакомится с девушкой по имени Гита. Она красива, но чересчур болтлива. Гита едет из Мумбай в родной город Бхатинд, затем, у нее есть планы сбежать к своему бойфренду.  Гита раздражает Адитью до такой степени, что он сходит с поезда. Она пытается вернуть его обратно, но сама опаздывает на поезд. Так они оба оказываются на заброшенной станции без багажа и денег. Начинается идиллическое путешествие по живописным местам Северной Индии и эта странная парочка встречает на своем пути: автобусы, такси, верблюжьи повозки, различных людей. Они пересекают равнины, пустыни, озера, до тех пор, пока не доберутся до Пенджаба.",
 "f-wd55609803": "Талантливый кинорежиссер на закате своего творческого пути оглядывается в прошлое и на него обрушивается поток ярких воспоминаний. Нежные чувства к матери, любовь и расставание, поиски счастья и успеха. Всё это приводит творца к важным размышлениям о жизни и искусстве, боли и славе.",
 "f-wd2656108": "Рейс лайнера, совершающего перелет в Мексику, начался как обычно: пассажиры пристегнули ремни, а командир корабля, включив автопилот, спокойно уснул. Но прямо над океаном оказалось, что самолет неисправен, исчезает интернет, и все гаджеты разом выходят из строя. Всех охватывает страх, ужас, отчаяние. Беспомощные пассажиры и экипаж, оказавшись пред лицом гибели, наконец-то должны стать сами собой. Так что несчастным на борту падающего самолета не остается ничего, как только петь и танцевать вслед за веселыми стюардами.",
 "f-wd838405": "Место действия фильма — огромный мегаполис, у которого нет названия. Именно здесь начинается странная эпидемия… эпидемия слепоты. Жители города теряют зрение один за другим и, это ставит целый мегаполис на грань жизни и смерти. Лишь одна женщина по неизвестной причине осталась видеть. Сможет ли она стать проводником для других?",
 "f-wd925448": "Действие этой замечательной драмы происходит на социалистической Кубе, где народ все еще наслаждается прелестями режима. Член молодежного, коммунистического союза, простой и недалекий парень, Давид, познакомился с гомосексуалистом Диего, настроенным против системы, увлекающимся искусством и литературой. Воспринявший сначала \"голубого\" в штыки, Давид постепенно узнает ближе его тонкое, доброе сердце, а когда того за поддержку выставки высылают из страны, расстаются они уже настоящими друзьями.",
 "f-wd1365797": "Заскучав в родном Париже, молодой Ксавье отправляется в удивительную и непредсказуемую Барселону, куда съезжаются студенты со всей Европы. Поселившись в маленькой квартирке вместе с шумным итальянцем, деловой англичанкой, дотошным немцем, жгучей испанкой и неутомимым датчанином, он намерен учиться и только учиться. Однако вскоре он понимает, что в такой веселой компании его непременно ждут неожиданные и забавные приключения, а может быть, даже головокружительная любовь!",
 "f-wd15731283": "Действия фильма начинаются в 1999 году в Китае. В небольшом провинциальном городке жизнь течет медленно и однообразно, пока полицейские не обнаруживают часть человеческой руки, а потом и сам труп. В ходе расследование полицейские находят еще несколько тел, после чего дело приобретает серьезный оборот. Местные жители очень напуганы происходящим, тем более что полиции так и не удается раскрыть серию жестоких убийств, поскольку выпавший снег скрывает все следы. Спустя несколько лет полицейские вновь сталкиваются с серийным убийцей, который совершает преступления очень похожие на те, что так и остались нераскрытыми. В ходе расследования детективам удается установить, что все жертвы так или иначе были связаны с одной местной женщиной, работающей в химчистке...",
 "f-wd1475995": "Экранизация пьесы М. Горького. Действие из царской России перенесено в Эдо — старый Токио эпохи позднего феодализма. На первый план поставлена любовная драма Пепла.",
 "f-wd232261": "Жил да был один мафиози местного значения. И задумал он, по совету своего верного психолога, возвыситься, разорив беззащитный парк аттракционов и построив на его месте огромный небоскрёб. И всё бы у него получилось, если бы под горячую руку распоясавшихся рэкетиров не попалась дюна-багги, любимый автомобиль двух приятелей — голубоглазого красавца и медведоподобного толстяка. И всё бы ничего, — ведь каждый может ошибиться, — так нет же! Загордился мафиози, заупрямился, несчастный, на свою голову, — не захотел платить по счетам!",
 "f-wd2529482": "Англия периода феодальных междоусобиц в годы правления Генриха IV. Повествование строится вокруг веселого похабника, выпивохи и хвастуна Джона Фальстафа, который постоянно попадает в истории и пытается сбить с истинного пути наследника престола.",
 "f-wd105998710": "Первая половина XVII века. Юный гасконец Д’Артаньян приезжает в Париж, чтобы примкнуть к элитным французским войскам - мушкетёрам. Но молодому горячему храбрецу всё никак не везёт: в результате попытки спасти женщину от похищения  Д’Артаньян едва остается жив. По прибытии в Париж он яростно ищет своих обидчиков, однако поиски заводят героя в самое сердце войны, где на карту поставлено будущее всей Франции. «Три мушкетера: Д’Артаньян» - первая часть новой экранизации знаменитого романа Александра Дюма.",
 "f-wd704513": "ЭнДжею уже за сорок, и он встревожен. Вдобавок к проблемам на работе его семья превратилась в клубок проблем — теща в коме, жена переживает душевный кризис, дочь впервые влюбилась, а сын слишком мудр для своих восьми лет. Внезапная встреча с давней возлюбленной Шерри, которую ЭнДжей бросил много лет назад, дает ему шанс начать новую жизнь. Вновь став романтиком, ЭнДжей тайком отправляется с Шерри в Японию, чтобы попытаться исправить свои ошибки.",
 "f-wd15303493": "В 1967 году молодой пекинский студент Чэнь Чжэнь отправляется жить среди кочевых пастухов Внутренней Монголии.  Оказавшись зажатыми между прогрессом цивилизации с юга и мародерством волков на севере, люди и животные борются, чтобы найти свое место в мире.",
 "f-wd1245864": "Не очень-то приятно, если ты родился в захолустной глуши, твоя мать повесилась, а родной брат — полный, хотя и добродушный, кретин. Казалось бы, ты всё сделал для того, чтобы навсегда порвать со своим прошлым: устроился на отличную, «денежную» работу в столице; заработал на «мобильник» и «БМВ»; обзавёлся престижной и богатой женой.  Но всё равно — в самый неподходящий момент ненавистное прошлое внезапно беспардонно вторгается в налаженную и комфортную жизнь. И приходится возвращаться в обветшалый отчий дом, где в подвале прячется свирепый самурай Мифуне; нанимать элитную проститутку, чтобы она заботилась о беспомощном придурке-брате.  И, в конце концов, приняв правила странной и нелепой игры, поставив на кон своё нелёгкое, заработанное потом и кровью, счастье, всё проиграть, но обрести взамен истинную любовь и безмятежный покой.",
 "f-wd112034047": "Все меняется в отношения портного средних лет и его жены, когда у него появляется новый красавец-ученик.",
 "f-wd28050177": "Немолодая женщина живёт одна в лесу недалеко от города. Она очень любит природу и животных и безуспешно пытается вразумить местных охотников не убивать зверей. Однажды без следа пропадают две её собаки, а затем в округе начинают происходить загадочные убийства.",
 "f-wd18180905": "Чосон, 1762 год. Король Ёнджо всегда стремился стать идеальным правителем. Его мать имеет самое низкое происхождение, а слухи говорят, что он убил старшего брата, чтобы стать королём. Сын Садо у него родился поздно, и Ёнджо назначает его наследником престола. У короля самые высокие ожидания насчёт кронпринца, и требования тоже.",
 "f-wd1631964": "В конце Второй мировой войны отряд японской императорской армии в Бирме сдается британским войскам. В дни испытаний и позора солдаты находят спасение в хоровом пении. Рядовой, которого все считают погибшим, скрывается под одеянием буддийского монаха…",
 "f-wd485580": "Неудачник Ким решает свести счёты с жизнью, бросившись с моста в реку Хан. Он не умеет плавать, так что смерть придёт быстро. Но по нелепой случайности его выносит на берег необитаемого острова, который находится около моста. В это же время, одна затворница, которая уже не выходит из своей комнаты 2 года, смотрит из окна, и видит мужчину на острове, а рядом надпись «HELP».",
 "f-wd2754899": "Трое художников — албанец Родольфо, француз Марсель и ирландец Шонар — оказываются в Париже без гроша в кармане. Они занимаются чистым искусством и искренне считают себя непризнанными гениями. Жизнь в двух шагах от успеха и в шаге от пропасти не дает им расслабиться, однако в их жизни находится место и любви, и трогательным попыткам перехитрить судьбу.",
 "f-wd1153431": "Через несколько сот лет после печально знаменитой битвы в заливе Данноура (1185) в далекой японской горной деревушке нарастает напряжение. Одетая в белое банда Гэндзи (из клана Тайра) и одетая в красное банда Хэйкэ (из клана Минамото) вступили в жестокое противостояние, порожденное слухами о спрятанном золоте. Когда в деревне появляется безымянный странник, обремененный темным прошлым, но мастерски владеющий искусством стрельбы, и Гэндзи, и Хэйкэ задают себе вопрос, на чью сторону он встанет. Битва за власть, предательство, похоть и любовь переплетаются, пропитывая землю кровью. Историческая война между кланами вновь обретает жизнь в формах «спагетти-вестерна».",
 "f-wd1754559": "Компьютерный вирус уничтожает сценарий фильма «Полицейский и шлюха». Несмотря на то, что Ларс и Нильс бились над сценарием два года, никто из них не может вспомнить, о чем он. Поэтому приятели садятся за новый сценарий под названием «Эпидемия» о страшной и загадочной болезни, охватившей Европу. Пока они будут искать вдохновения и денег на постановку, эпидемия вспыхнет по-настоящему.",
 "f-wd98078619": "В 15 лет Грета Тунберг впервые вышла к шведскому парламенту с плакатом «школьная забастовка за климат». Тогда о ней узнал режиссёр Натан Гроссман — и провёл с Гретой целый год, снимая всё, что с ней происходило. За это время она вдохновила тысячи ровесников по всему миру выйти на протесты, получила тысячи гневных комментариев, встретилась с Макроном и Папой Римским, появилась на обложках всех журналов и выступила в ООН. Но фильм Гроссмана — не столько про Грету-активистку, сколько про Грету-подростка: прямолинейную, самостоятельную, с феноменальной памятью и чувством юмора. В кадрах она не только перемещается между конференциями и произносит речи, но и спорит с отцом, танцует в пустой комнате, получает школьный аттестат, гладит лошадей. Она никогда не хотела быть популярной и чувствует себя некомфортно в путешествиях, вдали от семьи и любимых собак, но продолжает делать то, что считает важным.",
 "f-wd975564": "В фильме описываются попытки молодого солдата коммунистической армии взять под контроль небольшую крестьянскую общину, завоевать их сердца, вкупе с сердцем одной молодой сельчанки.",
 "f-wd1152485": "События фильма происходят в 1990-х годах и рассказывают о жизни двух китайских иммигрантов, живущих в Токио.",
 "f-wd20652078": "Кинорежиссёр Хам Чхун-су по ошибке приезжает в Сувон на день раньше, и ему нужно как-то скоротать время перед съёмкой дебатов. Он останавливается недалеко от старого дворца и встречает там художницу Юн Хи-джон, которая знакомит его со своими картинами. Они проводят время вместе, посещают её студию, ужинают, выпивают с друзьями художницы, постепенно чувства молодых людей друг к другу растут. Но когда девушка спрашивает, женат ли Чхун-су, у него нет выбора, кроме как сказать правду.",
 "f-wd164616": "Стокгольмский таксист, решивший подработать, соглашается на предложение своего босса начать торговать кокаином. Постепенно в дело оказываются замешаны югославская мафия, сбежавший из тюрьмы латиноамериканец, на эту мафию работавший, и серб, мечтающий покончить с криминальной жизнью.",
 "f-wd2279512": "Во втором фильме Кира, он же небезызвестный Лайт Ягами тщательно скрывает свою сущность от полиции и детектива L, при этом помогая отцу вести следствие, L - тщательно ищет того самого Киру, спинным мозгом чуя, что это и есть Лайт... Всё идёт своим чередом. И вдруг - хлобысь! С неба шлёпается вторая тетрадка! И попадает в ручонки к девушке по имени Аманэ Миса! И на свете становится одним Кирой больше...",
 "f-wd19840877": "Дораяки — традиционное японское пирожное, состоящее из двух бисквитных блинчиков с прослойкой из анко, пастой из бобов адзуки. 70-летняя Токуэ убеждает продавца дораяки Сэнтаро взять её на работу. Женщине известен рецепт удивительно вкусной бобовой пасты, и скоро ларёк Сэнтаро становится самым популярным местом в городе.",
 "f-wd4127314": "Бывший боксёр Чхоль-мин теперь работает охранником на парковке и развозит воду в бутылях. Однажды во время вечернего дежурства к нему приходит слепая девушка, которая с прежним охранником «смотрела» сериалы по вечерам. Между молодыми людьми завязывается дружба, а затем и любовь. Чхоль-мин чувствует, что должен защищать свою любимую и сделать всё возможное, чтобы вернуть ей возможность видеть.",
 "f-wd2054210": "Двадцатидвухлетняя Лена желает узнать все, что можно, о жизни современного общества. Она занимается моральными, социальными, политическими и эротическими исследованиями окружающего мира. Она представляет, как разговаривает с Мартином Лютером Кингом, участвует в демонстрации против войны во Вьетнаме, берет интервью у прохожих на улицах Стокгольма, а сама в это время продолжает крутить роман с женатым мужчиной, Бёрье, продавцом машин.",
 "f-wd1218309": "История алчного польского наемника и мексиканского крестьянина, чьи судьбы пересеклись в годы революции в Мексике.",
 "f-wd61650882": "1901 год, Испания. Марчела берет личность мужчины, чтобы жениться на своей возлюбленной Элисе.",
 "f-wd14326808": "Приквел рассказывает историю о еще молодом Ди и его первом задании в имперской полиции, а именно - расследовании дела о морском чудовище.",
 "f-wd1059733": "Токио. Он — пожилой мужчина, она — молодая женщина. Она ничего не знает о нем, ему кажется, что он знает о ней все. Он открывает перед ней двери своего жилища, она отдает ему свое тело. Однако обстоятельства их встречи не играют никакой роли в тех отношениях, которые устанавливаются между ними всего за одни сутки…",
 "f-wd1439492": "Проклятье, рожденное разъяренным разумом умирающего человека, не может сгинуть бесследно. Образ невинно загубленной души вновь и вновь является каждому, кто пытается постичь тайны ее страшной судьбы, замораживая кровь в жилах несчастных, ледяным ужасом неизбежного.  Спустя некоторое время после необъяснимых событий в проклятом доме, где разыгравшаяся много лет назад кровавая драма, положила начало цепи страшных смертей и таинственных исчезновений, очаровательная Кийоко, японская «королева ужасов», одержима идеей снять в этом зловещем месте фильм-расследование.  Она уверена, что создает сенсацию, и даже жуткие и необъяснимые события, преследующие Кийоко с начала съемок, не в силах изменить ее роковых намерений, ставших смертным приговором для кинозвезды и всех, кто ее окружает…",
 "f-wd23013805": "После просмотра странной видеозаписи над двумя девушками нависает проклятье. Чтобы избавиться от него, они отправляются в заброшенный дом. Подруги провоцируют столкновение двух смертоносных демонов и становятся свидетелями их эпической схватки.",
 "f-wd30601864": "Однажды летом трое мальчишек поспорили, круглые ли фейерверки на самом деле или плоские. Но как это выяснить, если не знаешь, как правильно на них смотреть? Между тем Назуна Оикава, девочка, что учится в той же школе, страдает из-за развода родителей и решает выбрать одного из парней, чтобы сбежать вместе с ним.",
 "f-wd259332": "Для участия в турнире мастеров восточных единоборств, знатоков стиля «Танцующий лев», в Пекин приезжают Вон Фэй-хун, его закадычный приятель-напарник Чун и юная Йе, кузина Фэй-хуна. Пока участники турнира готовятся к поединкам, Йе завязывает романтические отношения с русским дипломатом Тумановским…",
 "f-wd842442": "Несколько парней находят труп девушки, которая покончила с собой, оставив предсмертную записку. Этот случай особенно повлиял на одного из них по имени Мун, рэкетира на службе у триады (гонконгской мафии), вынужденного задуматься над собственной жизнью и смертельной болезнью его возлюбленной Пин."
};
